    *   The alcohol adjustment is applied within the `calculatePortionTargets` function.
    *   If the user includes alcohol, it reduces "Healthy Carbs" by 1, with a maximum reduction of 1. The `Math.max(0, ...)` ensures that Healthy Carbs never goes below 0.

6.  **"Prefer not to say" Logic:**

    *   The `getBasePortions` function defaults to the female portion plans if the user selects "prefer not to say" for their sex.

Here's the relevant code from `utils/portionCalculator.ts`:

```typescript
// Portion assignment based on sex, goal, size, activity level, and alcohol intake.
// "Prefer not to say" defaults to female portion assignments.
function calculatePortionTargets(sex: Sex, goal: Goal, height: number, weight: number, activityLevel: ActivityLevel, includeAlcohol: boolean, alcoholServings: number): PortionTargets {
  const basePortions = getBasePortions(sex, goal);
  const size = determineSize(sex, height, weight);
  let healthyCarbs = basePortions.healthyCarbs;

  healthyCarbs += size === 'small' ? -1 : size === 'large' ? 1 : 0;

  if (activityLevel === 'highlyActive') {
    basePortions.protein += 1;
    healthyCarbs += 1;
  }

  if (includeAlcohol && alcoholServings > 0) {
    healthyCarbs = Math.max(0, healthyCarbs - 1); // Max 1 carb reduction
  }

  return { ...basePortions, healthyCarbs };
}

// Base portion plans (Female/Male x Lose/Maintain/Build)
function getBasePortions(sex: Sex, goal: Goal): PortionTargets {
  const femalePlans = {
    lose: { protein: 3, vegetables: 4, fruit: 2, healthyCarbs: 2, fats: 2, nutsAndSeeds: 1 },
    maintain: { protein: 4, vegetables: 4, fruit: 2, healthyCarbs: 2, fats: 2, nutsAndSeeds: 1 },
    build: { protein: 5, vegetables: 4, fruit: 2, healthyCarbs: 3, fats: 2, nutsAndSeeds: 1 },
  };

  const malePlans = {
    lose: { protein: 4, vegetables: 4, fruit: 2, healthyCarbs: 3, fats: 3, nutsAndSeeds: 1 },
    maintain: { protein: 5, vegetables: 4, fruit: 2, healthyCarbs: 3, fats: 3, nutsAndSeeds: 1 },
    build: { protein: 6, vegetables: 4, fruit: 2, healthyCarbs: 4, fats: 3, nutsAndSeeds: 1 },
  };

  return sex === 'male' ? malePlans[goal] : femalePlans[goal]; // "Prefer not to say" defaults to female
}

// Size determination based on height and weight
function determineSize(sex: Sex, height: number, weight: number): Size {
  const femaleSmall = height < 64 || weight < 130; // 5'4" = 64 inches
  const femaleMedium = (height >= 64 && height <= 67) || (weight >= 130 && weight <= 165); // 5'7" = 67 inches
  const maleSmall = height < 67 || weight < 160; // 5'7" = 67 inches
  const maleMedium = (height >= 67 && height <= 72) || (weight >= 160 && weight <= 200); // 6'0" = 72 inches

  if (sex === 'male') {
    if (maleSmall) return 'small';
    if (maleMedium) return 'medium';
    return 'large';
  } else {
    if (femaleSmall) return 'small';
    if (femaleMedium) return 'medium';
    return 'large';
  }
}
```

